SELECT 
    (SELECT COUNT(*) FROM gasstations WHERE Country = 'Czech Republic' AND Segment = 'discount') -
    (SELECT COUNT(*) FROM gasstations WHERE Country = 'Slovakia' AND Segment = 'discount') AS Difference;

SELECT SUM(cost) AS total_expense
FROM expense
WHERE expense_date = '2019-08-20';

SELECT COUNT(*) 
FROM circuits 
WHERE location = 'Adelaide' AND country = 'Australia';

SELECT DisplayName
FROM users
WHERE strftime('%Y', CreationDate) = '2011';

SELECT LastEditorDisplayName
FROM posts
WHERE Title = 'Examples for teaching: Correlation does not mean causation';
